cat "$FILE" | python3 -c "
import json, sys

data = json.load(sys.stdin)
inner = json.loads(data['result'])
exps = inner['data']['experiments']

# Group by status
by_status = {}
for exp_id, exp in exps.items():
    status = exp.get('status', 'UNKNOWN')
    if status not in by_status:
        by_status[status] = []
    by_status[status].append((exp_id, exp))

print('=== STATUS SUMMARY ===')
for status, items in sorted(by_status.items()):
    print(f'{status}: {len(items)} experiments')
print()

# Now dump all experiments grouped by status
for status in ['COMPLETED', 'RUNNING', 'FAILED', 'PLANNED', 'BLOCKED', 'CANCELLED', 'UNKNOWN']:
    if status not in by_status:
        continue
    items = by_status[status]
    print(f'\\n{\"=\"*80}')
    print(f'STATUS: {status} ({len(items)} experiments)')
    print('='*80)
    for exp_id, exp in sorted(items, key=lambda x: x[1].get('updated_at', '')):
        print(f'\\n--- {exp_id} ---')
        print(f'  updated_at: {exp.get(\"updated_at\", \"N/A\")}')
        print(f'  created_at: {exp.get(\"created_at\", \"N/A\")}')
        if exp.get('completed_at'):
            print(f'  completed_at: {exp[\"completed_at\"]}')

        # Hypothesis
        hyp = exp.get('hypothesis', '')
        if hyp:
            print(f'  hypothesis: {hyp[:300]}')

        # Notes
        notes = exp.get('notes', '')
        if notes:
            if isinstance(notes, list):
                for n in notes:
                    print(f'  note: {str(n)[:200]}')
            else:
                print(f'  notes: {str(notes)[:300]}')

        # Metrics
        metrics = exp.get('metrics', {})
        if metrics:
            if isinstance(metrics, dict):
                for mk, mv in metrics.items():
                    print(f'  metric.{mk}: {json.dumps(mv) if isinstance(mv, (dict, list)) else mv}')
            else:
                print(f'  metrics: {str(metrics)[:300]}')

        # Conclusion
        conc = exp.get('conclusion', '')
        if conc:
            print(f'  conclusion: {str(conc)[:500]}')

        # Spec
        spec = exp.get('spec', {})
        if spec:
            if isinstance(spec, dict):
                desc = spec.get('description', spec.get('desc', ''))
                if desc:
                    print(f'  spec.description: {str(desc)[:200]}')
                cmd = spec.get('command', spec.get('cmd', ''))
                if cmd:
                    print(f'  spec.command: {str(cmd)[:150]}')
                model = spec.get('model', '')
                if model:
                    print(f'  spec.model: {model}')
                dataset = spec.get('dataset', '')
                if dataset:
                    print(f'  spec.dataset: {dataset}')
            else:
                print(f'  spec: {str(spec)[:200]}')

        print(f'  retry_count: {exp.get(\"retry_count\", 0)}')
" 2>&1

